function holidayDates(item) {
  var out = [];
  var p = item.date.split('-');
  var dt = new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]));
  var n = item.days || 1;
  for (var i = 0; i < n; i++) {
    var y = dt.getFullYear();
    var m = String(dt.getMonth() + 1).padStart(2, '0');
    var d = String(dt.getDate()).padStart(2, '0');
    out.push(y + '-' + m + '-' + d);
    dt.setDate(dt.getDate() + 1);
  }
  return out;
}

var HOLIDAY_OFF = Object.create(null);
var HOLIDAY_WORK = Object.create(null);
HOLIDAYS_2026_2027.forEach(function (item) {
  if (item.type === 'legal') holidayDates(item).forEach(function (k) { HOLIDAY_OFF[k] = item; });
  (item.arrange || []).forEach(function (a) {
    if (a.type === 'work') HOLIDAY_WORK[a.date] = item;
  });
});

function holidayYearCovered(dateStr) {
  var y = Number(String(dateStr).slice(0, 4));
  return y === 2026 || y === 2027;
}
